-- Coupa -> canonical PAYMENT (COUPA). Generated by tools/build_silver_sql.py.
SELECT 'COUPA' AS SOURCE_SLOT, 'Coupa' AS SOURCE_SYSTEM, SPLIT_PART(po.RAW:account.code::STRING, '-', 1) AS COMPANY_CODE, i.RAW:"invoice-number"::STRING AS INVOICE_ID,
  i.RAW:supplier.id::STRING AS SUPPLIER_ID, i.RAW:"invoice-date"::DATE AS INVOICE_DATE, DATEADD(day, 45, i.RAW:"invoice-date"::DATE) AS DUE_DATE,
  i.RAW:"payment-date"::DATE AS PAYMENT_DATE, i.RAW:total::FLOAT AS AMOUNT, 0::FLOAT AS DISCOUNT_TAKEN, i.RAW:currency.code::STRING AS CURRENCY,
  'Net 45' AS PAYMENT_TERMS
FROM {{ source('src_coupa', 'coupa_invoices') }} i LEFT JOIN {{ source('src_coupa', 'coupa_purchase_orders') }} po ON po.RAW:"po-number"::STRING = i.RAW:"order-header-num"::STRING
WHERE i.RAW:"payment-date"::DATE <= '2026-09-30'
